package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;

/** Production transparent native restoration and navigation routing, with Android boundaries adapted. */
public final class NotebookViewPaperTest {
    private static String source(String name)throws Exception{return new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/"+name+".java")),StandardCharsets.UTF_8);}
    private static String method(String s,String name){return NotebookWorkspaceActivationTest.method(s,name);}
    public static void main(String[] args)throws Exception{nativePaper();navigation();}
    private static void nativePaper()throws Exception{
        String source=source("NotebookInk");
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;public class NativeViewPaperFixture {",
            "static class Color {static final int TRANSPARENT=0,WHITE=-1;}static class PorterDuff {enum Mode {SRC}}static class Canvas {int clears;void drawColor(int c,PorterDuff.Mode mode){if(c!=0||mode!=PorterDuff.Mode.SRC)throw new AssertionError(\"native preview must clear alpha with SRC\");clears++;}void drawColor(int c){throw new AssertionError(\"opaque preview\");}void drawBitmap(Bitmap b,int x,int y,Object p){throw new AssertionError(\"paper copied into native surface\");}}",
            "static class Bitmap {static final int DENSITY_NONE=0;enum Config {ARGB_8888}int width=100,height=200;int getWidth(){return width;}int getHeight(){return height;}boolean isRecycled(){return false;}void setDensity(int n){}static Bitmap createBitmap(int w,int h,Config c){throw new AssertionError(\"View paper must not allocate a native page bitmap\");}}class Holder {boolean valid=true;int locks,posts;final Canvas canvas=new Canvas();Holder getSurface(){return this;}boolean isValid(){return valid;}Canvas lockCanvas(){locks++;return canvas;}void unlockCanvasAndPost(Canvas c){posts++;}}class View {final Holder holder=new Holder();Holder getHolder(){return holder;}}",
            "final View view=new View();boolean viewPaper,paperBindingDirty,paperDirty,restored=true,previewVisible,restoring,alive=true,failed,prepared=true,paused=true;Bitmap paperBitmap=new Bitmap(),paperStaging=new Bitmap();int surfaceWidth=100,surfaceHeight=200,binds,trackPosts;final List<String> events=new ArrayList<>();Object get(Object v,String n){if(!n.equals(\"getSurfacePicture\"))throw new AssertionError(n);return view;}Object call(Object v,String n,Class<?>[] types,Object... args){if(!n.equals(\"bindColor\")||!args[0].equals(0))throw new AssertionError(\"native paper is not transparent\");events.add(\"transparent\");binds++;return null;}void requirePaused(){if(!paused)throw new IllegalStateException(\"live input\");}void paintPaper(Bitmap b){throw new AssertionError(\"native rasterization\");}void repaintPaper(Bitmap b){throw new AssertionError(\"native rasterization\");}void replaceNativeTracks(boolean repaint){if(paperBitmap!=null||paperStaging!=null)throw new AssertionError(\"native paper retained\");events.add(\"tracks\");trackPosts++;}void fail(String s,Exception e){throw new AssertionError(s,e);}",
            method(source,"public void useViewPaper("),method(source,"public boolean usesViewPaper("),method(source,"private void restoreDocument("),method(source,"public boolean showScrollPreview("),method(source,"private boolean showViewPaperPreview("),
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run()throws Exception{NativeViewPaperFixture f=new NativeViewPaperFixture();check(!f.usesViewPaper(),\"ordinary native notebooks retain their existing behavior\");f.paused=false;try{f.useViewPaper();throw new AssertionError(\"changed during live input\");}catch(IllegalStateException expected){}check(!f.viewPaper,\"paper mode cannot change during a native stroke\");f.paused=true;f.useViewPaper();check(f.viewPaper&&f.paperBindingDirty&&f.paperDirty&&!f.restored,\"mode latches and requires transparent restoration\");f.restoreDocument();check(f.events.equals(Arrays.asList(\"transparent\",\"tracks\"))&&f.restored&&!f.paperDirty&&!f.paperBindingDirty&&f.paperBitmap==null&&f.paperStaging==null,\"bind transparent color and canonical tracks without rasterizing any page\");f.useViewPaper();f.restoreDocument();check(f.binds==1&&f.trackPosts==2,\"ordinary restoration does not rebind or allocate native paper\");check(f.showScrollPreview(null)&&f.previewVisible&&f.view.holder.canvas.clears==1&&f.view.holder.posts==1,\"scrolling clears only native trails while regular View paper stays visible\");f.showScrollPreview(null);check(f.view.holder.posts==1,\"subsequent scroll and pinch frames perform no native canvas work\");f.restoreDocument();check(!f.previewVisible&&f.binds==1,\"navigation completion restores bookkeeping without a paper-mode switch\");f.paperBindingDirty=true;f.restoreDocument();check(f.binds==2&&f.usesViewPaper(),\"surface recreation retains View paper and rebinds transparent color\");f.prepared=false;check(!f.showScrollPreview(null),\"unprepared surfaces wait rather than posting stale geometry\");System.out.println(\"NotebookNativeViewPaper: \"+checks+\" assertions passed (production transparent binding, zero native page bitmaps, preview cadence and surface rebind).\");}}"
        );NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.NativeViewPaperFixture",fixture);
    }
    private static void navigation()throws Exception{
        String source=source("NotebookActivity"),preview=method(source,"private void drawPreview(");
        // Adapt the legacy native bitmap boundary into a failing sentinel. Execute
        // the production routing, including first encounter with Markdown, intact.
        preview=preview.substring(0,preview.indexOf("if (preview == null)"))+"throw new AssertionError(\"native bitmap preview reached\");}catch(Exception e){throw new AssertionError(e);}}";
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;public class ViewNavigationFixture {class Ink {boolean mode;int previews;void useViewPaper(){mode=true;}boolean usesViewPaper(){return mode;}void showScrollPreview(Object bitmap){if(bitmap!=null)throw new AssertionError(\"flattened preview\");previews++;}}final Ink ink=new Ink();boolean active=true,dragging=true,gestureEngaged=true,figureNavigationPreview,visibleMarkdown=true;Object viewport=new Object(),shownError;int paths,pdf,frames;void prepareStrokePaths(){paths++;}void preparePdfBackgrounds(){pdf++;}boolean hasVisibleMarkdown(){return visibleMarkdown;}void refreshRestingPaper(){frames++;}",
            preview,
            "public static void run(){ViewNavigationFixture f=new ViewNavigationFixture();f.drawPreview();if(!f.ink.mode||f.frames!=1||f.ink.previews!=1)throw new AssertionError(\"first scrolling encounter enables persistent paper before legacy rasterization\");f.visibleMarkdown=false;f.drawPreview();if(f.frames!=2||f.ink.previews!=2)throw new AssertionError(\"pinching or moving Markdown offscreen cannot return to the native paper path\");f.dragging=false;f.figureNavigationPreview=true;f.drawPreview();if(f.frames!=3)throw new AssertionError(\"figure navigation retains the same scene\");f.active=false;f.drawPreview();if(f.frames!=3)throw new AssertionError(\"retired editor cannot draw\");System.out.println(\"NotebookViewNavigation: 4 assertions passed (actual scroll/zoom routing, first Markdown encounter and persistent mode).\");}}"
        );NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.ViewNavigationFixture",fixture);
    }
}
